#!/usr/bin/env node
// Actual fixed steerTurn + actual composer; capture only router boundary.
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {spawnSync} from 'node:child_process';import {pathToFileURL,fileURLToPath} from 'node:url';import {createHash} from 'node:crypto';
const baseline=process.env.PDRS_BASELINE??'/Users/da/ws/pilotdeck-rs/resources/PilotDeck',out=path.resolve(process.argv[2]);fs.mkdirSync(out);assert.equal(process.version,'v22.22.0');const revision='cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85';assert.equal(spawnSync('git',['-C',baseline,'rev-parse','HEAD'],{encoding:'utf8'}).stdout.trim(),revision);assert.equal(spawnSync('git',['-C',baseline,'diff','--quiet','HEAD','--','src','packages']).status,0);
const files=['src/gateway/client/InProcessGateway.ts','src/gateway/dialog/GatewayAttachmentTurnComposer.ts'];const sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');const {default:ts}=await import(pathToFileURL(path.join(baseline,'node_modules/typescript/lib/typescript.js')));const cfg=JSON.parse(fs.readFileSync(path.join(baseline,'tsconfig.json'),'utf8'));const options=ts.convertCompilerOptionsFromJson(cfg.compilerOptions,baseline).options;const identities=[];for(const file of files){const source=path.join(baseline,file),built=path.join(baseline,'dist',file.replace(/\.ts$/,'.js'));assert.equal(ts.transpileModule(fs.readFileSync(source,'utf8'),{fileName:source,compilerOptions:{...options,module:ts.ModuleKind.ESNext}}).outputText,fs.readFileSync(built,'utf8'));identities.push({file,sourceSha256:sha(source),distSha256:sha(built)});}
for(const key of Object.keys(process.env))delete process.env[key];Object.assign(process.env,{HOME:path.join(out,'home'),PILOT_HOME:path.join(out,'pilot'),PATH:'',LANG:'C',LC_ALL:'C',TZ:'UTC'});fs.mkdirSync(process.env.HOME);fs.mkdirSync(process.env.PILOT_HOME);fs.mkdirSync(path.join(out,'project'));fs.mkdirSync(path.join(out,'external'));fs.writeFileSync(path.join(out,'external','registered.txt'),'REGISTERED-STEER-CONTENT\n');fs.symlinkSync(path.join(out,'external','registered.txt'),path.join(out,'project','link.txt'));
const {InProcessGateway}=await import(pathToFileURL(path.join(baseline,'dist/src/gateway/client/InProcessGateway.js')));const {GatewayAttachmentTurnComposer}=await import(pathToFileURL(path.join(baseline,'dist/src/gateway/dialog/GatewayAttachmentTurnComposer.js')));
const base={sessionKey:'session',runId:'run',itemId:'item',message:'steered'};const registered=path.join(out,'project','link.txt');
const cases=[['plain',{}],['null-attachments',{attachments:null}],['empty-attachments',{attachments:[]}],['inline-text',{attachments:[{type:'text',content:'INLINE-STEER'}]}],['image',{attachments:[{type:'image',content:'aGVsbG8=',mimeType:'image/png',bytes:5}]}],['path-registered',{projectKey:path.join(out,'project'),attachments:[{type:'text',path:registered,name:'registered',metadata:{channelKey:'fixture'}}]}],['path-unregistered',{attachments:[{type:'text',path:registered,name:'unregistered'}]}],['missing-path',{attachments:[{type:'text',path:path.join(out,'missing.txt')}]}],['uploaded-ignored',{uploadedAttachments:[{uploadId:'not-acquired'}]}],['raw-object-message',{message:{raw:true}}],['undefined-message',{message:undefined}],['null-message',{message:null}],['block-null-message',{message:null,attachments:[{type:'text',content:'inline'}]}],['block-number-message',{message:12,attachments:[{type:'text',content:'inline'}]}],['null-entry',{attachments:[null]}],['number-entry',{attachments:[1]}],['false-attachments',{attachments:false}],['zero-attachments',{attachments:0}],['number-attachments',{attachments:1}],['object-attachments',{attachments:{}}],['object-zero-length',{attachments:{length:0}}],['string-attachments',{attachments:'x'}],['no-active-invalid',{attachments:[null],inactive:true}],['wrong-run-invalid',{attachments:[null],runId:'wrong'}],['no-resource-valid',{attachments:[{type:'text',content:'PREPARED-BEFORE-RESOURCE'}],noResource:true}],['no-resource-invalid',{attachments:[null],noResource:true}]];
const records=[];
for(const[name,extra]of cases){const gateway=Object.create(InProcessGateway.prototype);gateway.options={funasrInstallCommand:'npm run install:asr'};gateway.attachmentTurnComposer=new GatewayAttachmentTurnComposer();const calls=[];gateway.router={activeTurnRunId:()=>extra.inactive?undefined:'run',steer:async(sessionKey,item)=>{calls.push({sessionKey,item});return extra.noResource?{accepted:false,reason:'no_active_turn'}:{accepted:true};}};const input={...base,...extra};delete input.inactive;delete input.noResource;try{const result=await gateway.steerTurn(input);records.push({name,input,result,calls});}catch(error){records.push({name,input,error:{name:error.name,message:error.message,...(error.code?{code:error.code}:{})},calls});}}
const normalize=value=>typeof value==='string'?value.replaceAll(out,'<fixture>'):Array.isArray(value)?value.map(normalize):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([k,v])=>[k,normalize(v)])):value;
fs.writeFileSync(path.join(out,'oracle.json'),JSON.stringify({boundary:'actual frozen InProcessGateway.steerTurn and actual composer; active run/router outcome seam, no formal server claim',records:normalize(records)},null,2)+'\n');fs.writeFileSync(path.join(out,'identity.json'),JSON.stringify({node:process.version,revision,driverSha256:sha(fileURLToPath(import.meta.url)),identities},null,2)+'\n');console.log(JSON.stringify({cases:records.length,sha256:sha(path.join(out,'oracle.json'))}));
